<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import AppHeader from '../components/AppHeader.vue'
import RuleSurfaceScope from '../components/RuleSurfaceScope.vue'
import GameUpdateList from '../components/GameUpdateList.vue'
import RulePageNavigation from '../components/RulePageNavigation.vue'
import { canonicalRuleSlug, findRuleCategory, findRulePage, findRuleParentPage, loreNavigation, quickFaq, quickReferencePages, resolveSourceSections, ruleCategories, rulePageNavigation } from '../data/ruleCatalog'
import { rankModifier, structuredRule, visibleRuleFields } from '../rules/rulesEngine'
import { speciesData } from '../data/speciesData'
import { attributes, faiths, homelands, oaths, sparks, type AttributeId } from '../data/bramble'
import { coreActions } from '../data/coreAbilities'
import { startingPathOptions } from '../data/creationRules'
import { ADVENTURE_KIT_SELL_WP, STARTING_WEALTH_WP } from '../rules/economy'
import { WP_PER_SP } from '../rules/threadpieces'
import { loreSpells } from '../data/magicOptions'
import { loreDescriptions, spellDetails } from '../data/magicDetails'
import { sparkDetails } from '../data/characterOptions'
import targetingLineImage from '../assets/rules/aoe-line.png'
import targetingConeImage from '../assets/rules/aoe-cone.png'
import targetingOrbImage from '../assets/rules/aoe-orb.png'
import targetingBlockedImage from '../assets/rules/aoe-blocked.png'
import { externalMonsters, findExternalMonster, monsterCategories, monsterSlug, WOODLANDS_ENCOUNTERS_URL, WOODLANDS_MONSTERS_URL } from '../data/externalMonsters'
import { recordRecentRule } from '../services/ruleRecent'
import { ruleSourceDocuments, SPELL_HEART_DAMAGE_RULE, type RuleSourceBlock, type RuleSourceSection } from '../data/rulesCurrent'
import { TALENT_CATEGORIES, canonicalTalentName, classifyTalent, talentNameMatches } from '../data/talentCategories'
import { spellCostLabel } from '../rules/magicRules'
import { ABILITY_TYPE_KEYWORDS, abilityFeaturePillClass, abilityFeaturePillKeywords, abilityFeaturePillLabel, abilityPillLabel, abilityTypeClass, activeAbilityKeywords, canonicalAbilityType, traitPillKeywords } from '../rules/abilityPresentation'

const route=useRoute()
const slug=computed(()=>String(route.params.slug||''))
const page=computed(()=>findRulePage(slug.value))
const canonicalSlug=computed(()=>canonicalRuleSlug(slug.value))
const rawSourceSections=computed(()=>page.value?resolveSourceSections(page.value):[])
const ruleNavigation=computed(()=>rulePageNavigation(canonicalSlug.value))
const loreAttunedPreview=ref(false)
watch(slug,value=>{loreAttunedPreview.value=false;if(value)recordRecentRule(value)},{immediate:true})

type CreationAttributeRanks=Record<AttributeId,number>
function freshCreationAttributeRanks(){return Object.fromEntries(attributes.map(attribute=>[attribute.id,1])) as CreationAttributeRanks}
const creationAttributeRanks=ref<CreationAttributeRanks>(freshCreationAttributeRanks())
const creationAttributePointsRemaining=computed(()=>5-attributes.reduce((spent,attribute)=>spent+(creationAttributeRanks.value[attribute.id]-1),0))
function adjustCreationAttribute(id:AttributeId,amount:number){
  const current=creationAttributeRanks.value[id]
  if(amount>0&&(current>=3||creationAttributePointsRemaining.value<=0))return
  if(amount<0&&current<=1)return
  creationAttributeRanks.value={...creationAttributeRanks.value,[id]:current+amount}
}
function creationAttributeModifier(id:AttributeId){return rankModifier(creationAttributeRanks.value[id])}
function creationAttributeSecondary(id:AttributeId){
  const rank=creationAttributeRanks.value[id],modifier=rankModifier(rank)
  if(id==='agility')return[{label:'Accuracy',value:String(rank)},{label:'Aim',value:String(modifier)},{label:'Speed',value:`2 + ${modifier} = ${modifier+2}`}]
  if(id==='might')return[{label:'Fury',value:String(rank)},{label:'Brawl',value:String(modifier)}]
  if(id==='hide')return[{label:'Guts',value:String(rank)},{label:'Ward',value:String(modifier)}]
  if(id==='lore')return[{label:'Power',value:String(rank)},{label:'Control',value:String(modifier)}]
  return[{label:'Heart',value:String(rank)},{label:'Spirit',value:String(modifier)}]
}
watch(slug,(value,previous)=>{if(value==='character-creation'||previous==='character-creation')creationAttributeRanks.value=freshCreationAttributeRanks()})

const bannerModules=import.meta.glob('../assets/rule-banners/*.{png,PNG,jpg,JPG,jpeg,JPEG,webp,WEBP}',{eager:true,query:'?url',import:'default'}) as Record<string,string>
function bannerKey(value:string){const key=value.replace(/[^a-z0-9]+/gi,'').toLowerCase();return key==='athromundas'?'anthromundas':key}
function bannerStem(path:string){return (path.split('/').pop()||'').replace(/\.[^.]+$/,'').replace(/^banner[-_ ]*/i,'')}
const currentBanner=computed(()=>{
  if(!page.value)return''
  const wanted=Array.from(new Set([page.value.title,page.value.slug,page.value.title.replace(/^Lore of /i,''),page.value.slug.replace(/^lore[-_]?/i,'')].map(bannerKey).filter(Boolean)))
  const entry=Object.entries(bannerModules).find(([path])=>{
    const stem=bannerKey(bannerStem(path));return wanted.some(key=>stem===key||stem.endsWith(key)||key.endsWith(stem))
  })
  return entry?.[1]||''
})
function abilityTypes(values:string[]){return Array.from(new Set(traitKeywords(values).map(canonicalAbilityType).filter(value=>ABILITY_TYPE_KEYWORDS.has(value))))}
function traitFooterKeywords(values:string[],kind:'Heritage'|'Cultural',speciesName:string){return traitPillKeywords(values,kind,speciesName)}
const traitFooterClass=abilityFeaturePillClass
const traitFooterLabel=abilityFeaturePillLabel
function manaCostFromRule(text:string){const match=text.match(/\bCOST:\s*\[?([0-9]+)\]?\s*mana/i);return match?Number(match[1]):null}

function displayText(value:string){return value.replace(/\bProwess\b/g,'Agility').replace(/\bprowess\b/g,'agility')}
function isDialogue(value:string){return /\b(?:Watcher|Player|Selu):/.test(value)}
function dialogueParts(value:string){
  const parts:Array<{actor:string;text:string}>=[]
  const rx=/(Watcher|Player|Selu):\s*[“"]?([^”"]+)[”"]?/g
  let match:RegExpExecArray|null
  while((match=rx.exec(value)))parts.push({actor:match[1],text:match[2].trim()})
  return parts
}
function keywordParts(value:string){if(!/^KEYWORDS?:/i.test(value.trim()))return[];return value.split(':',2)[1].split('|').map(item=>item.trim()).filter(Boolean)}
function isKeywordBlock(block:RuleSourceBlock){return block.type==='paragraph'&&keywordParts(block.text).length>0}
function isExampleHeading(value:string){return /example/i.test(value)}

const sourceSections=computed(()=>{
  const entries=rawSourceSections.value
  if(page.value?.loreHeading){
    const entry=entries[0];if(!entry)return[]
    const headings=new Set(loreNavigation.map(item=>item.heading))
    const blocks=entry.section.blocks
    const start=blocks.findIndex(block=>block.type==='paragraph'&&block.text.trim()===page.value?.loreHeading)
    if(start<0)return[]
    let end=blocks.length
    for(let index=start+1;index<blocks.length;index++){const block=blocks[index];if(block.type==='paragraph'&&headings.has(block.text.trim())){end=index;break}}
    const section:RuleSourceSection={heading:page.value.loreHeading,blocks:blocks.slice(start+1,end)}
    return[{...entry,section}]
  }
  if(canonicalSlug.value==='to-damage')return entries.filter(entry=>!/^DAMAGE\s*[–-]\s*GUTS\s*=\s*TOTAL DAMAGE$/i.test(displayText(entry.section.heading).trim()))
  return entries
})

const loreIndex=computed(()=>loreNavigation.findIndex(item=>item.slug===canonicalSlug.value))
const breadcrumbSection=computed(()=>{
  if(loreIndex.value>=0||quickReferencePages.some(item=>item.slug===canonicalSlug.value))return'References'
  if(findExternalMonster(canonicalSlug.value))return'The Watcher'
  return findRuleCategory(canonicalSlug.value)?.title||'Rules'
})
const breadcrumbParent=computed(()=>findRuleParentPage(canonicalSlug.value)||null)
const currentCategoryLanding=computed(()=>ruleCategories.find(category=>category.landing.slug===canonicalSlug.value)||null)
const landingEntries=computed(()=>currentCategoryLanding.value?.pages||[])
function speciesImageUrl(name:string){return`/assets/species/${name.toLowerCase()}.png`}
function labeledParagraph(value:string){const text=displayText(value).trim();const match=text.match(/^([^:]{2,45}):\s+(.+)$/);return match?{label:match[1],body:match[2]}:{label:'',body:text}}
function bulletParts(value:string){const parts=displayText(value).split(/\s*•\s*/).map(part=>part.trim()).filter(Boolean);return parts.length>1?parts:[]}
function singleCellText(block:RuleSourceBlock){return block.type==='table'&&block.rows.length===1&&block.rows[0].length===1?displayText(block.rows[0][0]).trim():''}

const currentSpecies=computed(()=>canonicalSlug.value.startsWith('species-')?speciesData.find(item=>`species-${item.name.toLowerCase()}`===canonicalSlug.value)||null:null)
const currentMonster=computed(()=>findExternalMonster(canonicalSlug.value)||null)
const monsterGroups=computed(()=>monsterCategories.map(category=>{
  const monsters=externalMonsters.filter(monster=>monster.category===category.name)
  const parents=monsters.filter(monster=>!monster.group)
  const families=parents.map(parent=>({parent,children:monsters.filter(monster=>monster.group===parent.name)}))
  const groupedNames=new Set(families.flatMap(family=>[family.parent.name,...family.children.map(child=>child.name)]))
  for(const orphan of monsters.filter(monster=>!groupedNames.has(monster.name)))families.push({parent:orphan,children:[]})
  return{category,monsters,families}
}))
const talentSections=ruleSourceDocuments.talents.sections.filter(section=>section.heading!=='Overview'&&section.heading!=='TALENTS'&&!section.heading.startsWith('KEYWORDS'))
function talentRuleText(name:string){const section=talentSections.find(item=>talentNameMatches(item.heading,name));return section?.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'').join(' ')||''}
function talentRuleKeywords(name:string){const match=talentRuleText(name).match(/\bKEYWORDS?:\s*(.+)$/i);return activeAbilityKeywords(match?[match[1]]:[])}
function talentCategory(name:string){return classifyTalent(name,talentRuleText(name),talentRuleKeywords(name))}
const talentRuleGroups=computed(()=>TALENT_CATEGORIES.map(category=>({category,talents:talentSections.map(section=>canonicalTalentName(section.heading)).filter(name=>talentCategory(name)===category)})).filter(group=>group.talents.length))
const spellLoreBySlug:Record<string,string>={'lore-invocation':'Invocation','lore-flames':'Flames','lore-frost':'Frost','lore-hallows':'Hallows','lore-harmony':'Harmony','lore-life':'Life','lore-oath':'Oath','lore-wilds':'Wilds'}
const currentSpellLore=computed(()=>spellLoreBySlug[canonicalSlug.value]||'')
const currentLoreSpells=computed(()=>currentSpellLore.value?(loreSpells[currentSpellLore.value]||[]):[])
function spellRuleDetail(name:string){return spellDetails[name]}
const canPreviewLoreAttunement=computed(()=>Boolean(currentSpellLore.value&&currentSpellLore.value!=='Invocation'))
function displayedLoreCost(name:string){const detail=spellRuleDetail(name);if(!detail)return'Variable';return spellCostLabel({name,lore:detail.lore,baseCost:detail.manaCost,attunedLore:loreAttunedPreview.value&&canPreviewLoreAttunement.value?currentSpellLore.value:''})}
function spellLoreClass(name:string){return `spell-lore-${String(spellDetails[name]?.lore||'invocation').toLowerCase()}`}
const targetingRules=[
  {title:'Line',keyword:'LINE[n]',image:targetingLineImage,text:'A Line ability creates a straight path that never bends and affects every square it touches. The user chooses the direction; the Line continues from the user until it reaches its listed maximum length or an obstacle the ability cannot pass through.',example:'LINE[10] traces a straight line exactly ten squares long in the chosen direction. Every valid character, object, or terrain feature whose square lies along that path is affected.'},
  {title:'Cone',keyword:'CONE[n]',image:targetingConeImage,text:'A Cone ability begins adjacent to the user and extends outward in a triangular pattern on the grid. Its width grows as it advances, matching the listed area size.',example:'CONE[6] starts in the square directly in front of the user and expands to a roughly triangular shape six squares long and six squares wide at its farthest edge.'},
  {title:'Orb',keyword:'ORB[n]',image:targetingOrbImage,text:'For an Orb ability, choose a valid point within the Ability’s range. The Orb expands from that square as a square-shaped area whose size is determined by the Orb number. It ignores the user’s facing.',example:'ORB[7] creates a 7×7 block of squares from the chosen point. Every valid target whose square lies inside that area, including the edges, is affected.'},
]
const combatAttackCoreActions=coreActions.filter(action=>['MELEE STRIKE','RANGE STRIKE','ARCANE COMMAND'].includes(action.name))
const renewTheHeartAction=coreActions.find(action=>action.name==='RENEW THE HEART')!
const combatAbilityParagraphs=computed(()=>sectionByHeading('battle','COMBAT ABILITIES')?.blocks.flatMap(block=>block.type==='paragraph'?[block.text]:[])||[])
const encounterSetupHeadings=new Set(['THE BATTLES','COMBAT ENCOUNTER','DETERMINING POSITIONS','SQUARES & MEASUREMENTS'])
const encounterRoundHeadings=new Set(['INITIATIVE ORDER','ROUNDS & TURNS','TAKING YOUR TURN','PREFORMING ABILITIES','MANA'])
const encounterSetupSections=computed(()=>sourceSections.value.filter(entry=>encounterSetupHeadings.has(entry.section.heading)))
const encounterRoundSections=computed(()=>sourceSections.value.filter(entry=>encounterRoundHeadings.has(entry.section.heading)))
function coreActionTypeClass(keywords:string[]){const type=keywords.map(canonicalAbilityType).find(keyword=>ABILITY_TYPE_KEYWORDS.has(keyword)&&keyword!=='Core')||'Core';return abilityTypeClass(type)}
function coreActionPillClass(keyword:string){const canonical=canonicalAbilityType(keyword);return ABILITY_TYPE_KEYWORDS.has(canonical)?['ability-cost-pill',abilityTypeClass(canonical)]:['keyword-pill']}
function coreActionPillLabel(keyword:string){const canonical=canonicalAbilityType(keyword);return ABILITY_TYPE_KEYWORDS.has(canonical)?abilityPillLabel(canonical):canonical.toUpperCase()}
function traitKeywords(values:string[]){return activeAbilityKeywords(values)}
function skillTreeName(block:RuleSourceBlock){if(block.type!=='table'||block.rows.length<2)return'';const row=block.rows[1];return row.length===1&&/Skill Tree$/i.test(row[0])?displayText(row[0]):''}
function skillTreeTone(name:string){return name.toLowerCase().split(' ')[0]||'skill'}
function isBuildingSeluTable(block:RuleSourceBlock){const text=singleCellText(block);return /^Selu(?:’s| of )/i.test(text)}
function bracketParts(value:string){const text=displayText(value);const parts:Array<{text:string;bold:boolean}>=[];const rx=/(\[[+-]?\d+(?:\.\d+)?\])/g;let last=0,match:RegExpExecArray|null;while((match=rx.exec(text))){if(match.index>last)parts.push({text:text.slice(last,match.index),bold:false});parts.push({text:match[0],bold:true});last=match.index+match[0].length}if(last<text.length)parts.push({text:text.slice(last),bold:false});return parts.length?parts:[{text,bold:false}]}
function isLongNarrativeHeading(value:string){const t=displayText(value).trim();return t.startsWith('Packs, Herds, & Kinships (Optional Rule)')||t.startsWith('WATCHER’S NOTE')}
function narrativeParts(value:string){const t=displayText(value).trim();if(t.startsWith('WATCHER’S NOTE'))return{title:'WATCHER’S NOTE',body:t.replace(/^WATCHER’S NOTE\s*/,'')};const title='Packs, Herds, & Kinships (Optional Rule)';return{title,body:t.replace(title,'').trim()}}
const boxedRuleSlugs=new Set(['homeland','oath','faith','talents','adventuring-gear','lore-invocation','lore-flames','lore-frost','lore-hallows','lore-harmony','lore-life','lore-oath','lore-wilds'])
function boxedRulePage(){return boxedRuleSlugs.has(canonicalSlug.value)}
function abilityBoxPage(){return canonicalSlug.value==='talents'||Boolean(currentSpellLore.value)}
function entryRuleText(entry:{section:RuleSourceSection}){return entry.section.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'').join(' ')}
function entryKeywords(entry:{section:RuleSourceSection}){return activeAbilityKeywords(entry.section.blocks.filter(block=>block.type==='paragraph').flatMap(block=>block.type==='paragraph'?keywordParts(block.text):[]))}
function entryAbilityTypes(entry:{section:RuleSourceSection}){return Array.from(new Set(entryKeywords(entry).map(canonicalAbilityType).filter(value=>ABILITY_TYPE_KEYWORDS.has(value))))}
function entryDisplayKeywords(entry:{section:RuleSourceSection}){return entryKeywords(entry).filter(value=>!ABILITY_TYPE_KEYWORDS.has(canonicalAbilityType(value)))}
function entryMana(entry:{section:RuleSourceSection}){return manaCostFromRule(entryRuleText(entry))}
function equipmentTableRows(block:RuleSourceBlock){if(canonicalSlug.value!=='adventuring-gear'||block.type!=='table'||block.rows.length<2||block.rows[0].length<2)return[];const headers=block.rows[0].map(displayText);return block.rows.slice(1).filter(row=>row.some(cell=>String(cell).trim())).map(row=>({name:displayText(row[0]||'Item'),fields:row.slice(1).map((cell,index)=>({label:headers[index+1]||`Value ${index+1}`,value:displayText(cell||'—')}))}))}
function characterCreationStepParts(section:RuleSourceSection){const match=section.heading.match(/^(\d+)\.\s*(.+)$/);return match?{number:match[1],title:displayText(match[2])}:null}
function isCharacterCreationStep(section:RuleSourceSection){return canonicalSlug.value==='character-creation'&&Boolean(characterCreationStepParts(section))}
function isCharacterCreationAttributeTable(section:RuleSourceSection,block:RuleSourceBlock){return canonicalSlug.value==='character-creation'&&/^5\.\s*ATTRIBUTES DISTRIBUTION$/i.test(section.heading)&&block.type==='table'&&/^Attribute$/i.test(block.rows[0]?.[0]||'')}
function characterCreationStepNumber(section:RuleSourceSection){return Number(characterCreationStepParts(section)?.number||0)}
function creationGraphicStep(section:RuleSourceSection,step:number){return canonicalSlug.value==='character-creation'&&characterCreationStepNumber(section)===step}
const creationHomelandExample=homelands.find(item=>item.name==='Willowstead')||homelands[0]
const creationFaithExample='The Dreamtide'
const creationOathExample=oaths.find(item=>item[0]==='Balance')||oaths[0]
const creationStartingWealthSp=STARTING_WEALTH_WP/WP_PER_SP
const creationAdventureKitSellSp=ADVENTURE_KIT_SELL_WP/WP_PER_SP
const creationMaximumStartingWealthSp=creationStartingWealthSp+creationAdventureKitSellSp
type DeedEntry={name:string;flavor:string;objective:string;reward:string;keywords:string[]}
const sparkRuleSections=computed(()=>ruleSourceDocuments.sparks.sections.filter(section=>section.heading!=='Overview'&&section.blocks.length))
const sparkWhatSections=computed(()=>sparkRuleSections.value.filter(section=>['WHAT IS A SPARK?','KEYWORD LIBRARY'].includes(section.heading)))
const premadeSparkCards=computed(()=>sparks.map(([name,keywords])=>({name,keywords:keywords.split(',').map(value=>value.trim()).filter(Boolean),description:sparkDetails[name]?.description||''})))
const deedIntro=computed(()=>ruleSourceDocuments.deeds.sections.filter(section=>section.heading==='DEEDS'&&section.blocks.length).flatMap(section=>section.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'')))
const deedEntries=computed<DeedEntry[]>(()=>{
  const blocks=ruleSourceDocuments.deeds.sections.find(section=>section.heading==='DEEDS LIST')?.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text.trim():'').filter(Boolean)||[]
  const lines:string[]=[]
  for(let i=0;i<blocks.length;i++){const current=blocks[i];if(!/Objective \(Mechanical\):/.test(current)&&i+1<blocks.length&&/Objective \(Mechanical\):/.test(blocks[i+1])){lines.push(`${current} ${blocks[++i]}`)}else lines.push(current)}
  const knownNames=['Participation Trophy','Skill of the Day','Voice of the Table','Brush with Fate','Steady Hand','Heart of the Party','Calculated Edge','Wild Wanderer','Spark of Insight','Brushfire Courage','Steadfast Resolve','Tinker’s Triumph','Hope in the Ashes','Measured Breath','Inventor’s Spark','Gentle Guardian','Quiet Observer','Pathfinder’s Mark','Flicker of Faith','Rebel’s Smile','Scholar’s Patience','Trickster’s Turn','Lone Path','Silent Strength','Mind Like Water','Boundless Heart','Trailblazer','Wise Fool','Tether of Trust','Vision in Shadow','Master of the Moment']
  return lines.map(text=>{const name=knownNames.find(candidate=>text.startsWith(candidate))||text.split(' Objective (Mechanical):')[0];const rest=text.slice(name.length).trim();const match=rest.match(/^([^]*?)\s*Objective \(Mechanical\):\s*([^]*?)\s*Reward:\s*([^]*?)\s*Keywords:\s*([^]*)$/);if(!match)return null;return{name,flavor:match[1].trim(),objective:match[2].trim(),reward:match[3].trim(),keywords:match[4].split(',').map(x=>x.trim()).filter(Boolean)}}).filter((item):item is DeedEntry=>Boolean(item))
})
const creationSparkExample=computed(()=>premadeSparkCards.value.find(item=>item.name==='Healer')||premadeSparkCards.value[0])
const creationDeedExample=computed(()=>deedEntries.value.find(item=>item.name==='Gentle Guardian')||deedEntries.value[0])
const sparkStructureTitles:Record<string,string>={ROLEPLAY:'Personality Archetype',KEYWORDS:'Two Descriptors',DEEDS:'Alignment Reward'}
const sparkStructure=computed(()=>{
  const section=sparkRuleSections.value.find(item=>item.heading==='WHAT IS A SPARK?')
  return(section?.blocks||[]).flatMap(block=>{
    if(block.type!=='paragraph')return[]
    const parts=labeledParagraph(block.text),label=parts.label.toUpperCase()
    return[{label,title:sparkStructureTitles[label]||parts.label,text:parts.body}]
  })
})
function headingKey(value:string){return displayText(value).trim().toLowerCase().replace(/[’']/g,"'")}
function sectionByHeading(documentKey:string,heading:string){return ruleSourceDocuments[documentKey]?.sections.find(section=>headingKey(section.heading)===headingKey(heading))||null}
const toStrikeParagraphs=computed(()=>sectionByHeading('battle','TO HIT')?.blocks.flatMap(block=>block.type==='paragraph'?[block.text]:[])||[])
const strikeRollCards=computed(()=>[
  {title:'Melee Strike',text:toStrikeParagraphs.value[0]||''},
  {title:'Range Strike',text:toStrikeParagraphs.value[1]||''},
  {title:'Magic Strike',text:toStrikeParagraphs.value[2]||''},
].filter(card=>card.text))
const toDefendParagraphs=computed(()=>sectionByHeading('battle','TO DEFEND')?.blocks.flatMap(block=>block.type==='paragraph'?[block.text]:[])||[])
function isDamageCategorySection(section:RuleSourceSection){return canonicalSlug.value==='to-damage'&&section.heading==='DAMAGE CATEGORY'}
function isToSoakSection(section:RuleSourceSection){return canonicalSlug.value==='to-damage'&&section.heading==='TO SOAK'}
function commonSections(documentKey:string,names:readonly string[]){return names.map(name=>sectionByHeading(documentKey,name)).filter((section):section is RuleSourceSection=>Boolean(section))}
const commonHomelandSections=computed(()=>commonSections('homeland',homelands.map(item=>item.name)))
const commonOathSections=computed(()=>commonSections('oath',oaths.map(item=>item[0])))
const commonFaithSections=computed(()=>commonSections('faith',faiths))
const commonHeadingSets={homeland:new Set(homelands.map(item=>headingKey(item.name))),oath:new Set(oaths.map(item=>headingKey(item[0]))),faith:new Set(faiths.map(item=>headingKey(item)))}
function generalNarrativeSections(documentKey:string){if(documentKey!=='homeland'&&documentKey!=='oath'&&documentKey!=='faith')return[];const excluded=commonHeadingSets[documentKey];return (ruleSourceDocuments[documentKey]?.sections||[]).filter(section=>section.heading!=='Overview'&&!excluded.has(headingKey(section.heading))&&!(documentKey==='oath'&&section.heading==='COMMON OATHS'))}
function visibleNarrativeBlocks(section:RuleSourceSection){return section.blocks.filter(block=>!(block.type==='table'&&singleCellText(block).startsWith('WATCHER’S NOTE')))}
const faithWatcherNote=computed(()=>{for(const section of ruleSourceDocuments.faith.sections){for(const block of section.blocks){const text=singleCellText(block);if(text.startsWith('WATCHER’S NOTE'))return narrativeParts(text).body}}return''})
function isTableHeader(block:RuleSourceBlock,first:string){return block.type==='table'&&headingKey(block.rows[0]?.[0]||'')===headingKey(first)}
function clonedSection(section:RuleSourceSection,blocks:RuleSourceBlock[]):RuleSourceSection{return{heading:section.heading,blocks}}
const weaponRuleSections=computed(()=>ruleSourceDocuments.weapons.sections.filter(section=>section.heading!=='Overview').map(section=>clonedSection(section,section.blocks.filter(block=>!isTableHeader(block,'Quality')))).filter(section=>section.blocks.length))
const weaponQualitySections=computed(()=>ruleSourceDocuments.weapons.sections.map(section=>clonedSection(section,section.blocks.filter(block=>isTableHeader(block,'Quality')))).filter(section=>section.blocks.length))
const armorRuleSections=computed(()=>ruleSourceDocuments['armor-shields'].sections.filter(section=>section.heading!=='Overview'&&section.blocks.length))
const adventuringSectionGroups=computed(()=>[
  {title:'Threadpieces & Adventuring Kit',headings:['THREADPIECES','TYPES OF THREADPIECES','WASHER PIECES (WP)','NUT PIECES (NP)','SCREW PIECES (SP)','BOLT PIECES (BP)','Standard Exchange Rate','SELLING TREASURE','ADVENTURING KIT']},
  {title:'Traveler’s Gear',headings:['TRAVELER’S GEAR']},{title:'Field Kits',headings:['FIELD KITS']},{title:'Consumables',headings:['ALCHEMICAL LIQUIDS & CONSUMABLES']},{title:'Spellcasting Implements',headings:['SPELLCASTING IMPLEMENTS']},{title:'Trinkets',headings:['TRINKETS']},{title:'Accessories',headings:['ACCESSORIES']},{title:'Tools',headings:['TOOLS']},
].map(group=>({title:group.title,sections:group.headings.map(heading=>sectionByHeading('adventuring-gear',heading)).filter((section):section is RuleSourceSection=>Boolean(section))})).filter(group=>group.sections.length))
</script>

<template>
  <main class="page rule-reader-page">
    <AppHeader compact back-to="/rules" back-label="Back to Rules" prefer-back-to skip-back-prefix="/rules/read/" />
    <RuleSurfaceScope>
      <template v-if="page">
        <nav class="rule-breadcrumb" aria-label="Breadcrumb"><RouterLink to="/rules">Rules</RouterLink><span>›</span><template v-if="breadcrumbParent&&breadcrumbParent.slug!==page.slug"><RouterLink :to="`/rules/read/${breadcrumbParent.slug}`">{{ breadcrumbSection }}</RouterLink><span>›</span></template><strong>{{ page.title }}</strong></nav>
        <div class="page-title-block rule-reader-title card-surface" :class="{'rule-reader-title-fundamental':!currentSpecies}"><p v-if="!currentSpecies" class="eyebrow">{{ breadcrumbSection }}</p><h1>{{ page.title }}</h1><p v-if="page.summary">{{ page.summary }}</p></div>

        <template v-if="currentCategoryLanding">
          <section class="rule-content-card card-surface chapter-landing-page"><article class="rule-feature-box chapter-landing-intro"><header><h2>{{ page.title }}</h2></header><p>{{ page.summary }}</p></article><div class="chapter-landing-list"><RouterLink v-for="entry in landingEntries" :key="entry.slug" class="chapter-landing-link" :to="`/rules/read/${entry.slug}`"><span><strong>{{ entry.title }}</strong><small>{{ entry.summary }}</small></span><span aria-hidden="true">›</span></RouterLink></div></section>
        </template>

        <template v-else-if="page.slug==='playable-species'">
          <section class="rule-content-card card-surface playable-species-reader"><article class="rule-copy-card"><h2>Playable Species</h2><p>Choose a Species group, then open a Species to read its current rules.</p></article><details class="organized-rule-category playable-species-group" open><summary><span><h2>Woodlands</h2></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body playable-species-link-list"><RouterLink v-for="species in speciesData" :key="species.name" class="list-row" :to="`/rules/read/species-${species.name.toLowerCase()}`"><span class="list-row-copy"><span class="list-row-title">{{ species.name }}</span></span><svg class="row-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></RouterLink></div></details></section>
        </template>

        <template v-else-if="currentSpecies">
          <section class="species-rule-sheet">
            <article class="species-rule-lore card-surface"><header class="species-rule-panel-heading"><div><h2>{{ currentSpecies.name }} Lore</h2><small>{{ currentSpecies.pronunciation }}</small></div></header><div class="species-rule-layout"><div class="species-rule-lore-copy"><p>{{ currentSpecies.lore }}</p><p><strong>Language:</strong> {{ currentSpecies.language }}</p></div><div class="species-rule-side"><div class="species-rule-art"><div class="species-rule-art-frame"><img :src="speciesImageUrl(currentSpecies.name)" :alt="`${currentSpecies.name} species artwork`" /></div></div><blockquote class="species-rule-quote">“{{ currentSpecies.quote }}”</blockquote></div></div></article>
            <details class="organized-rule-category species-rule-lore-placeholder card-surface"><summary><span><h2>{{ currentSpecies.name }} Lore</h2><small>Expanded lore</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body species-lore-placeholder-body" aria-label="Species lore placeholder"></div></details>
            <details class="organized-rule-category species-rule-trait-section card-surface"><summary><span><h2>Heritage Traits</h2><small>{{ currentSpecies.speciesTraits.length }} traits</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body rule-box-grid"><article v-for="trait in currentSpecies.speciesTraits" :key="trait.name" class="trait-card heritage-trait-card species-trait-rule"><div class="trait-card-head"><div><h3>{{ trait.name }}</h3><small>{{ currentSpecies.name }} · Heritage</small></div><div class="trait-card-head-actions"><span v-if="manaCostFromRule(trait.text)!==null" class="mana-badge">{{ manaCostFromRule(trait.text) }} Mana</span></div></div><p v-if="structuredRule(trait.text).intro" class="rule-flavor">{{ structuredRule(trait.text).intro }}</p><div v-if="visibleRuleFields(trait.text).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(trait.text)" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in traitFooterKeywords(trait.keywords,'Heritage',currentSpecies.name)" :key="keyword" :class="traitFooterClass(keyword)">{{ traitFooterLabel(keyword) }}</span></div></article></div></details>
            <details class="organized-rule-category species-rule-trait-section card-surface"><summary><span><h2>Cultural Traits</h2><small>{{ currentSpecies.cultureTraits.length }} traits</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body rule-box-grid"><article v-for="trait in currentSpecies.cultureTraits" :key="trait.name" class="trait-card culture-trait-card culture-trait-rule"><div class="trait-card-head"><div><h3>{{ trait.name }}</h3><small>{{ currentSpecies.name }} · Cultural</small></div><div class="trait-card-head-actions"><span v-if="manaCostFromRule(trait.text)!==null" class="mana-badge">{{ manaCostFromRule(trait.text) }} Mana</span></div></div><p v-if="structuredRule(trait.text).intro" class="rule-flavor">{{ structuredRule(trait.text).intro }}</p><div v-if="visibleRuleFields(trait.text).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(trait.text)" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in traitFooterKeywords(trait.keywords,'Cultural',currentSpecies.name)" :key="keyword" :class="traitFooterClass(keyword)">{{ traitFooterLabel(keyword) }}</span></div></article></div></details>
          </section>
        </template>



        <template v-else-if="page.slug==='talents'">
          <section class="organized-rule-stack character-reference-page"><details v-for="group in talentRuleGroups" :key="group.category" class="organized-rule-category card-surface"><summary><span><h2>{{ group.category }}</h2><small>{{ group.talents.length }} {{ group.talents.length===1?'Talent':'Talents' }}</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body review-box-list"><article v-for="talent in group.talents" :key="talent" class="talent-detail-card full-rule-entry" :class="abilityTypes(talentRuleKeywords(talent)).map(abilityTypeClass)"><div class="talent-detail-head"><div><h2>{{ talent }}</h2></div><div class="talent-head-actions"><span v-if="manaCostFromRule(talentRuleText(talent))!==null" class="mana-badge">{{ manaCostFromRule(talentRuleText(talent)) }} Mana</span></div></div><p v-if="structuredRule(talentRuleText(talent)).intro" class="rule-flavor"><em>{{ structuredRule(talentRuleText(talent)).intro }}</em></p><div v-if="visibleRuleFields(talentRuleText(talent)).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(talentRuleText(talent))" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(talentRuleKeywords(talent))" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div></article></div></details></section>
        </template>

        <template v-else-if="currentSpellLore">
          <section class="organized-rule-stack"><details class="organized-rule-category card-surface lore-reader-category" open><summary><span><h2>{{ currentSpellLore==='Invocation'?'Invocation Spells':`Lore of ${currentSpellLore}` }}</h2><label v-if="canPreviewLoreAttunement" class="lore-attunement-preview-toggle" @click.stop><span>Attuned</span><span class="switch"><input v-model="loreAttunedPreview" type="checkbox" @click.stop /><span></span></span></label><small>{{ currentLoreSpells.length }} spells</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body review-spell-column"><article v-if="loreDescriptions[currentSpellLore]" class="rule-feature-box lore-fluff-rule-card"><header><h3>{{ currentSpellLore==='Invocation'?'Invocation':`Lore of ${currentSpellLore}` }}</h3></header><p>{{ loreDescriptions[currentSpellLore] }}</p></article><article v-for="spell in currentLoreSpells" :key="spell" class="spell-detail-card full-rule-entry" :class="spellLoreClass(spell)"><div class="spell-detail-head"><div><h2>{{ spell }}</h2></div><span class="mana-badge">{{ displayedLoreCost(spell) }}</span></div><p v-if="spellRuleDetail(spell)?.flavor" class="rule-flavor"><em>{{ spellRuleDetail(spell)?.flavor }}</em></p><div v-if="visibleRuleFields(spellRuleDetail(spell)?.rules||'').length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(spellRuleDetail(spell)?.rules||'')" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div v-if="spellRuleDetail(spell)?.keywords?.length" class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(spellRuleDetail(spell)?.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div></article></div></details></section>
        </template>

        <template v-else-if="page.slug==='combat-abilities-targeting'">
          <section class="combat-targeting-page organized-rule-stack">
            <article class="rule-feature-box combat-framework-card"><header><h2>Combat Abilities</h2></header><p v-for="line in combatAbilityParagraphs" :key="line">{{ displayText(line) }}</p></article>
            <section class="core-attack-reference"><header class="section-graphic-heading"><span class="eyebrow">CORE COMBAT ACTIONS</span><h2>Choose One Core Attack</h2><p>Each character normally has one Core Combat Action each round. These three actions are the shared starting points for attacking and spellcasting.</p></header><div class="core-attack-grid"><article v-for="action in combatAttackCoreActions" :key="action.name" class="rule-feature-box core-attack-card" :class="coreActionTypeClass(action.keywords)"><header><div><h3>{{ action.name }}</h3><small>{{ action.flavor }}</small></div><span v-if="action.cost" class="mana-badge">{{ action.cost }}</span></header><div class="core-attack-fields"><div v-for="field in action.fields" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in action.keywords" :key="keyword" :class="coreActionPillClass(keyword)">{{ coreActionPillLabel(keyword) }}</span></div></article></div></section>
            <article class="rule-feature-box targeting-intro-card"><header><h2>Combat Range</h2></header><div class="keyword-pill-row targeting-touch-pill-row"><span class="keyword-pill">TOUCH</span></div><p>Abilities use their listed range to determine which targets or points can be chosen. <strong>Touch</strong> requires the target to be within the weapon’s range. If no range is specified, Touch defaults to <strong>[1] square</strong>.</p></article>
            <article class="rule-feature-box targeting-rule-card"><header><div><h2>Direct</h2><span class="keyword-pill">DIRECT</span></div></header><div class="targeting-rule-layout compact"><div><p>A Direct ability affects one chosen valid target within the Ability’s range rather than creating an area. Intervening characters or objects do not change the target unless the Ability or another rule says otherwise. If an Ability can target an ally, the user may target themself unless its rules prohibit it.</p></div></div></article>
            <article v-for="rule in targetingRules" :key="rule.title" class="rule-feature-box targeting-rule-card"><header><div><h2>{{ rule.title }}</h2><span class="keyword-pill">{{ rule.keyword }}</span></div></header><div class="targeting-rule-layout"><div><p>{{ rule.text }}</p><p class="rule-example-copy"><strong>Example:</strong> {{ rule.example }}</p></div><img :src="rule.image" :alt="`${rule.title} Ability targeting diagram`" /></div></article>
            <article class="rule-feature-box targeting-rule-card"><header><h2>Impassable Collision</h2></header><div class="targeting-rule-layout compact"><div><p>Impassable terrain stops an Ability’s area unless that Ability explicitly says it can pass through the obstacle. Any portion beyond the blocking terrain is not affected; the remaining valid portion of the area stays intact.</p></div><img :src="targetingBlockedImage" alt="Cone Ability area blocked by impassable terrain" /></div></article>
          </section>
        </template>

        <template v-else-if="page.slug==='attacking-defending'">
          <section class="organized-rule-stack attack-defense-page">
            <article class="rule-feature-box strike-intro-card"><header><h2>Attacking &amp; Defending</h2></header><p>Attack rolls are opposed by Ward. The attacker rolls the Stat named by the Strike or Spell, the defender rolls Ward, and the higher total wins. The defender wins ties unless a more specific rule states otherwise.</p></article>
            <div class="attack-defense-graphic" role="img" aria-label="Attack total is compared against Ward total. The higher total wins and the defender wins ties."><div class="attack-node"><small>ATTACKER</small><strong>3d10 + Brawl, Aim, or Control</strong><span>+ condition(s)</span></div><b>VS</b><div class="defense-node"><small>DEFENDER</small><strong>3d10 + Ward</strong><span>+ condition(s)</span></div><div class="resolution-node"><small>RESOLUTION</small><strong>Higher total succeeds</strong><span>Ties go to the defender.</span></div></div>
            <section class="strike-roll-grid"><article v-for="roll in strikeRollCards" :key="roll.title" class="rule-feature-box strike-roll-card"><header><h2>{{ roll.title }}</h2></header><p>{{ displayText(roll.text) }}</p></article></section>
            <article class="rule-feature-box ward-defense-card"><header><h2>Ward Defense</h2></header><p v-for="line in toDefendParagraphs" :key="line">{{ displayText(line) }}</p></article>
            <article class="rule-example-card attack-defense-example"><span class="eyebrow">EXAMPLE</span><p>An attacker finishes with a total of <strong>21</strong>. The defender’s Ward roll also totals <strong>21</strong>. Because the totals are tied, the defender successfully defends.</p></article>
          </section>
        </template>

        <template v-else-if="page.slug==='encounter-rounds'">
          <section class="encounter-rounds-page organized-rule-stack">
            <article v-for="entry in encounterSetupSections" :key="entry.section.heading" class="rule-feature-box encounter-rule-card"><header v-if="entry.section.heading!=='THE BATTLES'"><h2>{{ displayText(entry.section.heading) }}</h2></header><template v-for="(block,index) in entry.section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article>
            <div class="encounter-round-flow" role="img" aria-label="Encounter flow: determine positions, roll Initiative, resolve start of round, take turns in Initiative order, then begin the next round."><span><small>1</small><strong>Set Positions</strong></span><b>→</b><span><small>2</small><strong>Roll Initiative</strong></span><b>→</b><span><small>3</small><strong>Start of Round</strong></span><b>→</b><span><small>4</small><strong>Turns in Order</strong></span><b>→</b><span><small>5</small><strong>Next Round</strong></span></div>
            <article v-for="entry in encounterRoundSections" :key="entry.section.heading" class="rule-feature-box encounter-rule-card"><header><h2>{{ displayText(entry.section.heading) }}</h2></header><template v-for="(block,index) in entry.section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article>
          </section>
        </template>

        <template v-else-if="page.slug==='encounters-threat-level'">
          <section class="rule-content-card card-surface external-rule-page"><article class="rule-feature-box encounter-rating-box"><header><h2>Encounter Rating (ER)</h2></header><p>Encounter difficulty is measured with Encounter Rating rather than character level. For an individual character or creature, add its Attribute ranks together and divide the total by 6. The referenced example rounds 16 ÷ 6 down from 2.67 to ER 2.</p></article><article class="rule-feature-box"><header><h2>Group Encounter Rating</h2></header><p>Add the individual ER values of the characters in the group. That total represents the group’s overall encounter strength.</p></article><article class="rule-feature-box"><header><h2>Encounter Difficulty</h2></header><p>The source recommends using creatures roughly two ER above or below the character or group ER as the normal encounter range.</p></article><a class="secondary-button external-source-link" :href="WOODLANDS_ENCOUNTERS_URL" target="_blank" rel="noopener noreferrer">Open Source Encounter Reference</a></section>
        </template>

        <template v-else-if="page.slug==='monsters' || page.slug==='critters'">
          <section class="monster-index-stack"><article class="rule-feature-box monster-source-intro"><header><h2>{{ page.slug==='critters'?'Critters & Companions':'Monsters of Anthro Mundas' }}</h2></header><p>The creature reference is organized first by parent category and then, for monsters with variants, by their monster type.</p></article><template v-for="group in monsterGroups" :key="group.category.name"><details v-if="group.monsters.length && (page.slug==='monsters'?group.category.name!=='Companions':group.category.name==='Companions')" class="monster-category-box organized-rule-category card-surface" open><summary><span><h2>{{ group.category.name }}</h2><small>{{ group.category.summary }}</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body monster-family-stack"><template v-for="family in group.families" :key="family.parent.name"><details v-if="family.children.length" class="monster-family-box"><summary><span><strong>{{ family.parent.name }}</strong><small>{{ family.children.length }} {{ family.children.length===1?'variant':'variants' }}</small></span><span aria-hidden="true">⌄</span></summary><div class="monster-link-grid"><RouterLink :to="`/rules/read/${monsterSlug(family.parent.name)}`"><strong>{{ family.parent.name }}</strong></RouterLink><RouterLink v-for="monster in family.children" :key="monster.name" :to="`/rules/read/${monsterSlug(monster.name)}`"><strong>{{ monster.name }}</strong></RouterLink></div></details><RouterLink v-else class="monster-family-link" :to="`/rules/read/${monsterSlug(family.parent.name)}`"><strong>{{ family.parent.name }}</strong></RouterLink></template></div></details></template><a class="secondary-button external-source-link" :href="WOODLANDS_MONSTERS_URL" target="_blank" rel="noopener noreferrer">Open Source Monster Reference</a></section>
        </template>

        <template v-else-if="currentMonster">
          <section class="rule-content-card card-surface external-monster-page"><article class="rule-feature-box monster-profile-box"><header><div><small>{{ currentMonster.category }}</small><h2>{{ currentMonster.name }}</h2></div></header><p>{{ currentMonster.summary }}</p><p v-if="currentMonster.group"><strong>Family:</strong> {{ currentMonster.group }}</p><p class="source-status-note">This creature is listed as an individual entry in the external Woodlands monster reference. The current crawl exposes its index placement but not a reliable complete stat block, so Brambleheart does not invent missing statistics.</p></article><a class="secondary-button external-source-link" :href="WOODLANDS_MONSTERS_URL" target="_blank" rel="noopener noreferrer">Open Source Monster Reference</a></section>
        </template>

        <template v-else-if="page.slug==='sparks-deeds'">
          <section class="deeds-rule-page organized-rule-stack character-reference-page">
            <article class="rule-feature-box spark-rule-card character-reference-section"><header><h2>What is a Spark?</h2></header><div class="spark-structure-grid"><article v-for="item in sparkStructure" :key="item.title" class="spark-structure-card"><small>{{ item.label }}</small><strong>{{ item.title }}</strong><p>{{ item.text }}</p></article></div><template v-for="section in sparkWhatSections.filter(item=>item.heading==='KEYWORD LIBRARY')" :key="section.heading"><template v-for="(block,index) in section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p></template></template></article>
            <details class="organized-rule-category card-surface premade-sparks-menu"><summary><span><h2>Premade Sparks</h2><small>{{ premadeSparkCards.length }} Sparks</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body narrative-card-grid"><article v-for="spark in premadeSparkCards" :key="spark.name" class="rule-feature-box choice-summary narrative-choice-card spark-choice-card detail-tone-spark"><header><h3>{{ spark.name }}</h3></header><p v-if="spark.description">{{ spark.description }}</p><div class="keyword-pill-row"><span v-for="keyword in spark.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></article></div></details>
            <article class="rule-feature-box deed-intro-box character-reference-section"><header><h2>Deeds</h2></header><div class="deed-structure-copy"><p v-for="line in deedIntro" :key="line"><strong v-if="labeledParagraph(line).label" class="rule-inline-label">{{ labeledParagraph(line).label }}:</strong>{{ labeledParagraph(line).body }}</p></div><div class="deed-example-grid"><article v-for="deed in deedEntries.slice(0,3)" :key="deed.name" class="rule-feature-box deed-rule-card deed-example-graphic"><header><h3>{{ deed.name }}</h3><strong>{{ deed.reward }}</strong></header><p v-if="deed.flavor">{{ deed.flavor }}</p><div class="deed-objective"><small>OBJECTIVE</small><span>{{ deed.objective }}</span></div><div class="deed-keyword-row"><small>KEYWORDS</small><span v-for="keyword in deed.keywords" :key="keyword">{{ keyword }}</span></div></article></div></article>
            <details class="organized-rule-category card-surface deed-cards-menu"><summary><span><h2>All Deeds</h2><small>{{ deedEntries.length }} examples</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body deed-rule-list"><article v-for="deed in deedEntries" :key="deed.name" class="rule-feature-box deed-rule-card"><header><h3>{{ deed.name }}</h3><strong>{{ deed.reward }}</strong></header><p v-if="deed.flavor">{{ deed.flavor }}</p><div class="deed-objective"><small>OBJECTIVE</small><span>{{ deed.objective }}</span></div><div class="deed-keyword-row"><small>KEYWORDS</small><span v-for="keyword in deed.keywords" :key="keyword">{{ keyword }}</span></div></article></div></details>
          </section>
        </template>

        <template v-else-if="page.slug==='homeland'||page.slug==='oath'||page.slug==='faith'">
          <section class="organized-rule-stack narrative-rule-page character-reference-page"><article v-for="section in generalNarrativeSections(page.slug)" :key="section.heading" class="rule-feature-box narrative-rule-card"><header><h2>{{ displayText(section.heading) }}</h2></header><template v-for="(block,index) in visibleNarrativeBlocks(section)" :key="index"><p v-if="block.type==='paragraph'"><strong v-if="labeledParagraph(block.text).label" class="rule-inline-label">{{ labeledParagraph(block.text).label }}:</strong> {{ labeledParagraph(block.text).body }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article><details class="organized-rule-category card-surface common-narrative-menu"><summary><span><h2>{{ page.slug==='homeland'?'Common Homelands':page.slug==='oath'?'Common Oaths':'Common Faiths' }}</h2><small>{{ page.slug==='homeland'?commonHomelandSections.length:page.slug==='oath'?commonOathSections.length:commonFaithSections.length }} entries</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body narrative-card-grid"><article v-for="section in (page.slug==='homeland'?commonHomelandSections:page.slug==='oath'?commonOathSections:commonFaithSections)" :key="section.heading" class="rule-feature-box choice-summary narrative-choice-card" :class="`detail-tone-${page.slug}`"><header><h3>{{ displayText(section.heading) }}</h3></header><template v-for="(block,index) in visibleNarrativeBlocks(section)" :key="index"><p v-if="block.type==='paragraph'"><strong v-if="labeledParagraph(block.text).label" class="rule-inline-label">{{ labeledParagraph(block.text).label }}:</strong> {{ labeledParagraph(block.text).body }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article></div></details><article v-if="page.slug==='faith'&&faithWatcherNote" class="rule-narrative-note watcher-note-panel"><strong>WATCHER’S NOTE</strong><p>{{ faithWatcherNote }}</p></article></section>
        </template>

        <template v-else-if="page.slug==='adventuring-gear'">
          <section class="organized-rule-stack equipment-rules-organized character-reference-page"><details class="organized-rule-category card-surface"><summary><span><h2>Weapons</h2><small>Profiles &amp; weapon rules</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><article v-for="section in weaponRuleSections" :key="section.heading" class="rule-feature-box equipment-source-card"><header v-if="section.heading!=='WEAPONS'"><h3>{{ displayText(section.heading) }}</h3></header><template v-for="(block,index) in section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article></div></details><details class="organized-rule-category card-surface"><summary><span><h2>Weapon Qualities</h2><small>Special weapon properties</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><article v-for="section in weaponQualitySections" :key="section.heading" class="rule-feature-box equipment-source-card"><template v-for="(block,index) in section.blocks" :key="index"><div v-if="block.type==='table'" class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article></div></details><details class="organized-rule-category card-surface"><summary><span><h2>Armor &amp; Shields</h2><small>Protective equipment</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><article v-for="section in armorRuleSections" :key="section.heading" class="rule-feature-box equipment-source-card"><header v-if="section.heading!=='ARMOR & SHIELDS'"><h3>{{ displayText(section.heading) }}</h3></header><template v-for="(block,index) in section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article></div></details><details v-for="group in adventuringSectionGroups" :key="group.title" class="organized-rule-category card-surface"><summary><span><h2>{{ group.title }}</h2><small>{{ group.sections.length }} section{{ group.sections.length===1?'':'s' }}</small></span><span aria-hidden="true">⌄</span></summary><div class="organized-rule-category-body"><article v-for="section in group.sections" :key="section.heading" class="rule-feature-box equipment-source-card"><header><h3>{{ displayText(section.heading) }}</h3></header><template v-for="(block,index) in section.blocks" :key="index"><p v-if="block.type==='paragraph'">{{ displayText(block.text) }}</p><div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex">{{ displayText(cell) }}</td></tr></tbody></table></div></template></article></div></details></section>
        </template>

        <template v-else-if="page.slug==='faq'"><section class="rule-content-card card-surface faq-reader"><article v-for="item in quickFaq" :key="item.q" class="rule-copy-card faq-row"><h2>{{ item.q }}</h2><p>{{ item.a }}</p></article></section></template>
        <template v-else-if="page.slug==='changes-updates'"><section class="changes-reader"><article class="rule-content-card card-surface changes-reader-intro"><h2>Changes &amp; Updates</h2><p>Game Updates record changes to Brambleheart rules. The newest update is expanded; earlier updates remain available below in reverse chronological order.</p></article><GameUpdateList /></section></template>

        <template v-else>
          <section v-if="page.note" class="info-card rule-source-note"><strong>Source Note</strong><p>{{ displayText(page.note) }}</p></section>
          <section v-if="sourceSections.length" class="rule-content-card card-surface fundamental-style-source">
            <article v-for="(entry,index) in sourceSections" :key="`${entry.document}-${entry.section.heading}-${index}`" class="rule-copy-card source-section-card source-rule-section" :class="{'example-source-card':isExampleHeading(entry.section.heading),'boxed-rule-entry':boxedRulePage(),'creation-step-section':isCharacterCreationStep(entry.section),'creation-path-step':creationGraphicStep(entry.section,6)}">
              <header v-if="entry.section.heading!=='Overview'&&abilityBoxPage()" class="boxed-rule-titlebar"><h2>{{ displayText(entry.section.heading) }}</h2><div class="rule-title-costs"><span class="ability-cost-pill type-ability">ABILITY</span><span v-for="type in entryAbilityTypes(entry)" :key="type" :class="['ability-cost-pill',abilityTypeClass(type)]">{{ abilityPillLabel(type) }}</span><span v-if="entryMana(entry)!==null" class="mana-badge">{{ entryMana(entry) }} Mana</span></div></header>
              <header v-else-if="isCharacterCreationStep(entry.section)" class="creation-step-heading"><span>{{ characterCreationStepParts(entry.section)?.number }}</span><div><h2>{{ characterCreationStepParts(entry.section)?.title }}</h2></div></header>
              <h2 v-else-if="entry.section.heading!=='Overview'">{{ displayText(entry.section.heading) }}</h2>
              <div v-if="loreIndex>=0&&index===0" class="rule-page-banner-placeholder anthro-rule-banner" :class="{empty:!currentBanner}" :style="currentBanner?{backgroundImage:`url(${currentBanner})`}:undefined" aria-hidden="true"></div>
              <template v-for="(block,blockIndex) in entry.section.blocks" :key="blockIndex">
                <div v-if="isKeywordBlock(block)&&abilityBoxPage()" class="keyword-pill-row"><span v-for="keyword in entryDisplayKeywords(entry)" :key="keyword" class="keyword-pill">{{ displayText(keyword) }}</span></div>
                <p v-else-if="isKeywordBlock(block)" class="rule-keyword-line"><strong>Keywords:</strong> {{ keywordParts(block.type==='paragraph'?block.text:'').map(displayText).join(' · ') }}</p>
                <template v-else-if="block.type==='paragraph'"><div v-if="isDialogue(block.text)" class="dialogue-example-box"><p v-for="part in dialogueParts(block.text)" :key="`${part.actor}-${part.text}`"><strong>{{ part.actor }}:</strong> <span>{{ displayText(part.text) }}</span></p></div><div v-else-if="bulletParts(block.text).length" class="rule-bullet-block"><p>{{ bulletParts(block.text)[0] }}</p><ul><li v-for="part in bulletParts(block.text).slice(1)" :key="part">{{ part }}</li></ul></div><p v-else :class="{'example-copy':isExampleHeading(entry.section.heading)}"><strong v-if="labeledParagraph(block.text).label" class="rule-inline-label">{{ labeledParagraph(block.text).label }}:</strong><template v-for="(part,partIndex) in bracketParts(labeledParagraph(block.text).body)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><span v-else>{{ part.text }}</span></template></p></template>
                <section v-else-if="isCharacterCreationAttributeTable(entry.section,block)" class="creation-attribute-demo"><header><strong>Spend 5 Points</strong><span>{{ creationAttributePointsRemaining }} points remaining</span></header><div class="creation-attribute-list"><article v-for="attribute in attributes" :key="attribute.id" class="creation-attribute-row" :class="`attribute-${attribute.id}`"><div class="creation-attribute-copy"><h3>{{ attribute.name }}</h3><p>{{ attribute.description }}</p><div class="creation-secondary-stats"><span v-for="secondary in creationAttributeSecondary(attribute.id)" :key="secondary.label"><small>{{ secondary.label }}</small><strong>{{ secondary.value }}</strong></span></div></div><div class="creation-attribute-controls"><div class="creation-rank-summary"><span><small>Rank</small><strong>{{ creationAttributeRanks[attribute.id] }}</strong></span><span><small>Modifier</small><strong>+{{ creationAttributeModifier(attribute.id) }}</strong></span></div><div class="creation-rank-stepper"><button type="button" :disabled="creationAttributeRanks[attribute.id]<=1" :aria-label="`Decrease ${attribute.name}`" @click="adjustCreationAttribute(attribute.id,-1)">−</button><strong>{{ creationAttributeRanks[attribute.id] }}</strong><button type="button" :disabled="creationAttributeRanks[attribute.id]>=3||creationAttributePointsRemaining<=0" :aria-label="`Increase ${attribute.name}`" @click="adjustCreationAttribute(attribute.id,1)">+</button></div></div></article></div><small class="creation-demo-note">Rules-reader example only. These values reset when you leave this page or reload.</small></section>
                <div v-else-if="block.rows.length===1&&block.rows[0].length===1&&isDialogue(block.rows[0][0])" class="dialogue-example-box"><p v-for="part in dialogueParts(block.rows[0][0])" :key="`${part.actor}-${part.text}`"><strong>{{ part.actor }}:</strong> <span>{{ displayText(part.text) }}</span></p></div>
                <article v-else-if="isBuildingSeluTable(block)" class="creation-example rule-selu-example"><strong>Building Selu:</strong> <span>{{ singleCellText(block).replace(/^Selu(?:’s| of the Wandering Reeds)?\s*/i,'Selu ') }}</span></article>
                <article v-else-if="skillTreeName(block)" class="skill-tree-card" :class="`skill-tree-${skillTreeTone(skillTreeName(block))}`"><header><h3>{{ skillTreeName(block) }}</h3></header><div class="skill-tree-list"><div v-for="(row,rowIndex) in block.rows.slice(2)" :key="rowIndex"><strong>{{ displayText(row[0]||'') }}</strong><span>{{ displayText(row[1]||'') }}</span><small>{{ displayText(row[2]||'') }}</small></div></div></article>
                <article v-else-if="singleCellText(block)&&isLongNarrativeHeading(singleCellText(block))" class="rule-narrative-note"><strong>{{ narrativeParts(singleCellText(block)).title }}</strong><p>{{ narrativeParts(singleCellText(block)).body }}</p></article>
                <h3 v-else-if="singleCellText(block)" class="source-table-title">{{ singleCellText(block) }}</h3>
                <div v-else-if="equipmentTableRows(block).length" class="equipment-rule-card-grid"><article v-for="item in equipmentTableRows(block)" :key="`${item.name}-${blockIndex}`" class="equipment-rule-card detail-tone-equipment"><header><strong>{{ item.name }}</strong></header><div><span v-for="field in item.fields" :key="field.label"><small>{{ field.label }}</small><template v-for="(part,partIndex) in bracketParts(field.value)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><b v-else>{{ part.text }}</b></template></span></div></article></div>
                <div v-else class="rule-table-wrap"><table class="rule-source-table"><tbody><tr v-for="(row,rowIndex) in block.rows" :key="rowIndex"><td v-for="(cell,cellIndex) in row" :key="cellIndex"><template v-for="(part,partIndex) in bracketParts(cell)" :key="partIndex"><strong v-if="part.bold" class="bracket-number">{{ part.text }}</strong><span v-else>{{ part.text }}</span></template></td></tr></tbody></table></div>
              </template>
              <article v-if="page.slug==='spell-types-targeting'&&entry.section.heading==='ENHANCES & HEXES'" class="rule-feature-box core-action-card renew-heart-reference" :class="coreActionTypeClass(renewTheHeartAction.keywords)"><header><div><h3>{{ renewTheHeartAction.name }}</h3><small>{{ renewTheHeartAction.flavor }}</small></div><span v-if="renewTheHeartAction.cost" class="mana-badge">{{ renewTheHeartAction.cost }}</span></header><div class="core-attack-fields"><div v-for="field in renewTheHeartAction.fields" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div><div class="keyword-pill-row"><span v-for="keyword in renewTheHeartAction.keywords" :key="keyword" :class="coreActionPillClass(keyword)">{{ coreActionPillLabel(keyword) }}</span></div></article>
              <aside v-if="page.slug==='spell-types-targeting'&&entry.section.heading==='SPELL RANGE'" class="rule-cross-reference spell-range-targeting-reference"><strong>Targeting</strong><p>For battlefield areas and shaped effects, use the shared Combat Abilities &amp; Targeting rules.</p><RouterLink class="secondary-button compact-action" to="/rules/read/combat-abilities-targeting">Targeting</RouterLink></aside>
              <div v-if="creationGraphicStep(entry.section,1)" class="creation-reference-graphic creation-trait-graphic"><article class="trait-card heritage-trait-card"><header><small>INHERITED</small><h3>Heritage Traits</h3></header><p>Innate features of your chosen Species.</p></article><article class="trait-card culture-trait-card"><header><small>LEARNED</small><h3>Cultural Traits</h3></header><p>Learned traditions that may be exchanged during Character Creation.</p></article></div>
              <div v-if="creationGraphicStep(entry.section,2)" class="creation-reference-graphic creation-example-pair"><article v-if="creationSparkExample" class="choice-summary creation-spark-example detail-tone-spark"><h3>{{ creationSparkExample.name }}</h3><p>{{ creationSparkExample.description }}</p><div class="keyword-pill-row"><span v-for="keyword in creationSparkExample.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></article><article v-if="creationDeedExample" class="choice-summary creation-spark-example creation-deed-example detail-tone-spark"><h3>{{ creationDeedExample.name }}</h3><p>{{ creationDeedExample.flavor }}</p><div class="creation-example-detail-grid"><span><small>OBJECTIVE</small><strong>{{ creationDeedExample.objective }}</strong></span><span><small>REWARD</small><strong>{{ creationDeedExample.reward }}</strong></span></div><div class="keyword-pill-row"><span v-for="keyword in creationDeedExample.keywords" :key="keyword" class="keyword-pill">{{ keyword }}</span></div></article></div>
              <div v-if="creationGraphicStep(entry.section,3)" class="creation-reference-graphic creation-single-example"><article class="choice-summary creation-narrative-example detail-tone-homeland"><h3>{{ creationHomelandExample.name }}</h3><p>Begins with two Skills at Rank 1.</p><div class="keyword-pill-row"><span v-for="skill in creationHomelandExample.skills" :key="skill" class="keyword-pill">{{ skill }} · Rank 1</span></div></article></div>
              <div v-if="creationGraphicStep(entry.section,4)" class="creation-reference-graphic creation-example-pair"><article class="choice-summary creation-narrative-example detail-tone-faith"><h3>{{ creationFaithExample }}</h3><p>A belief tradition that frames meaning, ritual, and belonging.</p></article><article class="choice-summary creation-narrative-example detail-tone-oath"><h3>{{ creationOathExample[0] }}</h3><p>{{ creationOathExample[1] }}</p></article></div>
              <div v-if="creationGraphicStep(entry.section,6)" class="creation-path-reference"><div class="path-choice-grid"><article v-for="path in startingPathOptions" :key="path.id" class="path-choice-card creation-path-card" :class="`path-${path.id}`" aria-disabled="true"><span class="path-choice-kicker">{{ path.kicker }}</span><strong class="path-choice-title">{{ path.title }}</strong><p>{{ path.description }}</p></article></div></div>
              <div v-if="creationGraphicStep(entry.section,7)" class="starting-equipment-panel creation-equipment-graphic"><div class="adventure-kit-bar"><div><small>STARTING PACKAGE</small><strong>Adventure Kit</strong></div><strong>Included</strong></div><div class="creation-equipment-budget"><span><small>STARTING THREADPIECES</small><strong>{{ creationStartingWealthSp }} sp</strong><b>{{ STARTING_WEALTH_WP.toLocaleString('en-US') }} wp</b></span><span><small>RETURN KIT</small><strong>+{{ creationAdventureKitSellSp }} sp</strong><b>+{{ ADVENTURE_KIT_SELL_WP }} wp</b></span><span><small>MAX BUDGET AFTER RETURN</small><strong>{{ creationMaximumStartingWealthSp }} sp</strong><b>{{ (STARTING_WEALTH_WP+ADVENTURE_KIT_SELL_WP).toLocaleString('en-US') }} wp</b></span></div></div>
              <template v-if="isDamageCategorySection(entry.section)">
                <div class="damage-category-graphic" role="img" aria-label="Standard damage uses full Guts, Direct damage uses half Guts rounded up, and Lethal damage bypasses Guts."><article><small>STANDARD</small><strong>Damage − Full Guts</strong><span>Use all applicable Guts.</span></article><article><small>DIRECT</small><strong>Damage − Half Guts</strong><span>Round Guts up; minimum [1].</span></article><article><small>LETHAL</small><strong>Damage − 0 Guts</strong><span>Lethal bypasses Guts.</span></article></div>
                <aside class="damage-heart-callout"><strong>SPELL HEART DAMAGE</strong><p>{{ SPELL_HEART_DAMAGE_RULE }}</p></aside>
              </template>
              <div v-if="isToSoakSection(entry.section)" class="damage-formula-graphic" role="img" aria-label="Damage minus Guts equals Total Damage. Example: 8 Standard damage minus Selu's 1 Guts equals 7 Total Damage."><div class="damage-formula-row"><span><small>Incoming</small><strong>Damage</strong><b>8</b></span><span class="formula-operator">−</span><span><small>Selu’s Defense</small><strong>Guts</strong><b>1</b></span><span class="formula-operator">=</span><span class="damage-formula-result"><small>Health Lost</small><strong>Total Damage</strong><b>7</b></span></div><p class="damage-formula-caption"><strong>Example:</strong> Selu has Guts [1]. Against [8] Standard damage, Selu loses [7] Health after Guts is applied.</p></div>
            </article>
          </section>
          <section v-else-if="!page.note" class="empty-state card-surface compact-empty"><h2>Rule Text Unavailable</h2><p>This page is organized in the reader but has no supplied source text in the current rules package.</p></section>
        </template>

        <RulePageNavigation :navigation="ruleNavigation" />
      </template>

      <section v-else class="empty-state card-surface compact-empty"><h2>Rule Not Found</h2><p>The requested rule page is not available.</p><RouterLink class="primary-button" to="/rules">Back to Rules</RouterLink></section>
    </RuleSurfaceScope>
  </main>
</template>

